import pandas as pd
import numpy as np
import re

path='/root/environment/data/ckd_lab_data.csv'
df = pd.read_csv(path)
# parse numeric columns except patient_id
num_cols = [c for c in df.columns if c!='patient_id']

def parse_val(x):
    if pd.isna(x):
        return np.nan
    if isinstance(x, (int,float)):
        return float(x)
    s = str(x).strip()
    if s=='' or s.lower() in ['na','nan','null']:
        return np.nan
    # replace comma with dot
    s = s.replace(',', '.')
    # remove spaces
    s = re.sub(r'\s+', '', s)
    try:
        return float(s)
    except:
        return np.nan

parsed = df.copy()
for c in num_cols:
    parsed[c]=df[c].apply(parse_val)

print('rows', len(parsed))
print('missing rows any', parsed[num_cols].isna().any(axis=1).sum())

summary=[]
for c in num_cols:
    col=parsed[c]
    summary.append((c, col.min(), col.max()))

# print some extremes
for c, mn, mx in summary:
    if mn<0 or mx>1000:
        print(c, mn, mx)
